(()=>{'use strict';
const $=s=>document.querySelector(s);
if(!document.querySelector('.title-fauna')){let fauna=document.createElement('div');fauna.className='title-fauna';fauna.setAttribute('aria-hidden','true');fauna.innerHTML='<i class="tf tf-squid"></i><i class="tf tf-shark"></i><i class="tf tf-angler"></i><i class="tf tf-oarfish"></i>';document.getElementById('title')?.prepend(fauna)}
let modal=document.createElement('div');
modal.className='modal';
modal.id='resetDataModal';
modal.innerHTML='<div class="panel reset-panel"><div class="bigicon">⚠️</div><h2>全データをリセットしますか？</h2><p class="reset-warning">進行中の潜航、深海生物図鑑、称号・実績、アセンションの解放がすべて消えます。消去すると元に戻せません。</p><div class="reset-actions"><button class="btn" id="resetCancel">取り消す</button><button class="btn reset-confirm" id="resetConfirm">すべて消去</button></div></div>';
document.body.appendChild(modal);
let settingsMenu=document.createElement('div');settingsMenu.className='modal title-hub-modal';settingsMenu.id='titleSettingsModal';settingsMenu.innerHTML='<div class="panel title-hub-panel settings-hub-panel modal-shell"><header class="modal-shell-head"><div><small>GAME OPTIONS</small><h2>⚙️ 設定</h2></div></header><div class="modal-shell-body title-hub-grid settings-hub-grid"><button data-setting="audio"><i>♫</i><span><b>音量調節</b><small>BGM・効果音</small></span></button><button data-setting="reset" class="danger"><i>↺</i><span><b>データリセット</b><small>すべての進行を消去</small></span></button><button data-setting="debug" id="settingsDebug"><i>🛠</i><span><b>デバッグ</b><small>デバッグモード OFF</small></span></button></div><footer class="modal-shell-foot"><button class="btn" data-hub-close>閉じる</button></footer></div>';document.body.appendChild(settingsMenu);
function closeHub(menu){menu.classList.remove('on')}
function openSettings(){let debug=$('#settingsDebug'),enabled=window.isAbyssDebugEnabled?.()||false;debug.classList.toggle('active',enabled);debug.querySelector('small').textContent=`デバッグモード ${enabled?'ON':'OFF'}`;settingsMenu.classList.add('on');window.applyFuri?.(settingsMenu)}
$('#titleSettingsMenu').onclick=openSettings;$('#titleRelicCodex').onclick=()=>window.openAbyssRelicCollection?.();
settingsMenu.onclick=e=>{if(e.target===settingsMenu||e.target.closest('[data-hub-close]'))return closeHub(settingsMenu);let action=e.target.closest('[data-setting]')?.dataset.setting;if(!action)return;closeHub(settingsMenu);if(action==='audio')window.openAbyssAudioSettings?.();if(action==='reset')$('#resetAllData')?.click();if(action==='debug')window.toggleAbyssDebug?.()};
$('#titleBestiary').onclick=()=>window.openAbyssBestiary?.();
$('#resetAllData').onclick=()=>{modal.classList.add('on');window.applyFuri?.(modal)};
$('#resetCancel').onclick=()=>modal.classList.remove('on');
modal.onclick=e=>{if(e.target===modal)modal.classList.remove('on')};
$('#resetConfirm').onclick=async()=>{let b=$('#resetConfirm');b.disabled=true;b.textContent='消去中…';window.__abyssRunComplete=true;try{let keys=[];for(let i=0;i<localStorage.length;i++){let k=localStorage.key(i);if(k?.startsWith('abyss'))keys.push(k)}keys.forEach(k=>localStorage.removeItem(k));window.__abyssRecoveredSave=null;await window.clearAbyssBackup?.()}catch(e){}location.reload()};
let newRunModal=document.createElement('div');newRunModal.className='modal';newRunModal.id='newRunConfirmModal';newRunModal.innerHTML='<div class="panel reset-panel"><div class="bigicon">🌊</div><h2>最初から潜りますか？</h2><p class="reset-warning">「つづきから」の中断データは削除され、今の潜航には戻れなくなります。</p><div class="reset-actions"><button class="btn" id="newRunCancel">取り消す</button><button class="btn gold" id="newRunConfirm">中断データを消して開始</button></div></div>';document.body.appendChild(newRunModal);let bypassNewRun=false,newButton=$('#newGame'),hasInterruptedRun=()=>{try{let x=JSON.parse(localStorage.getItem('abyssDeck')||'null');return !!(x&&Array.isArray(x.deck)&&x.deck.length&&x.hp>0)}catch(e){return false}},guardNewRun=e=>{if(bypassNewRun||!hasInterruptedRun())return;e.preventDefault();e.stopImmediatePropagation();newRunModal.classList.add('on');window.applyFuri?.(newRunModal)};newButton?.addEventListener('click',guardNewRun,true);newButton?.addEventListener('touchend',guardNewRun,true);$('#newRunCancel').onclick=()=>newRunModal.classList.remove('on');$('#newRunConfirm').onclick=()=>{newRunModal.classList.remove('on');try{localStorage.removeItem('abyssDeck');localStorage.removeItem('abyssDeckBackup')}catch(e){}window.__abyssRecoveredSave=null;bypassNewRun=true;newButton.click();setTimeout(()=>bypassNewRun=false,0)};newRunModal.onclick=e=>{if(e.target===newRunModal)newRunModal.classList.remove('on')};
const localInterruptedRun=hasInterruptedRun;hasInterruptedRun=()=>localInterruptedRun()||!!window.__abyssRecoveredSave;
window.applyFuri?.($('#title'));
})();
